            { id: 'SI.L2-3.14.6', level: 2, title: 'Inbound & Outbound Traffic Monitoring', requirement: 'Monitor organizational systems, including inbound and outbound communications traffic, to detect attacks and indicators of potential attacks.', evidence: ['IDS/IPS configurations', 'Network monitoring tools', 'Traffic analysis reports', 'SIEM alert rules'], interviewSubjects: ['SOC analysts', 'Network security engineers'], testProcedures: ['Verify traffic monitoring coverage', 'Test attack detection capability', 'Review monitoring alert rules'] },
            { id: 'SI.L2-3.14.7', level: 2, title: 'Unauthorized Use Detection', requirement: 'Identify unauthorized use of organizational systems.', evidence: ['UEBA configurations', 'Behavioral baseline documentation', 'Anomaly detection reports'], interviewSubjects: ['SOC analysts', 'Security engineers'], testProcedures: ['Verify unauthorized use detection capabilities', 'Test anomaly detection effectiveness', 'Review detection coverage'] }
